-- Run once in phpMyAdmin on the existing database. Run owner-dashboard-migration.sql first if its GPS/delivery columns are not present.
ALTER TABLE menu_items ADD COLUMN variant VARCHAR(30) NOT NULL DEFAULT 'Single' AFTER name;
ALTER TABLE orders ADD COLUMN delivery_fee DECIMAL(10,2) NOT NULL DEFAULT 0 AFTER subtotal, ADD COLUMN packaging_fee DECIMAL(10,2) NOT NULL DEFAULT 0 AFTER delivery_fee, ADD COLUMN distance_km DECIMAL(7,2) NOT NULL DEFAULT 0 AFTER packaging_fee;
UPDATE menu_items SET is_available=0;
